# components of non-5 and erosion layer depth
from collections import deque
H,W=A.shape
lab=np.full((H,W),-1,int); comps=[]
for r in range(H):
 for c in range(W):
  if A[r,c]!=5 and lab[r,c]<0:
   k=len(comps); q=deque([(r,c)]); lab[r,c]=k; comp=[]
   while q:
    x,y=q.popleft(); comp.append((x,y))
    for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=nx<H and 0<=ny<W and A[nx,ny]!=5 and lab[nx,ny]<0:
      lab[nx,ny]=k;q.append((nx,ny))
   comps.append(comp)
# layer d by 8-neighbor boundary erosion
D=np.full((H,W),-1,int)
for k,co in enumerate(comps):
 remaining=set(co); d=0
 while remaining:
  boundary=set()
  for r,c in remaining:
   if any((r+dr,c+dc) not in remaining for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc): boundary.add((r,c))
  for p in boundary: D[p]=d
  remaining-=boundary; d+=1
for k,co in enumerate(comps):
 seeds=[(r,c,A[r,c],D[r,c]) for r,c in co if A[r,c] not in (8,5)]
 print(k,len(co),(min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co)),seeds)
